form.addEventListener('submit', function (e) {
  e.preventDefault();

  const selected = form.querySelector('input[name="notification"]:checked');

  if (!selected) {
    errorMsg.classList.add('visible');
    successMsg.classList.remove('visible');
    form.querySelector('input[name="notification"]').focus();
    return;
  }

